/**
 * Output Snapshots — preserves files generated by tools and uploaded by users
 * across the lifetime of a conversation, even if the original files are later
 * moved or deleted by the user.
 *
 * Storage layout:
 *   {appData}/conversations/{convId}/outputs/
 *   ├── manifest-log.jsonl     (append-only records, keyed by normalized originalPath)
 *   ├── manifest.json          (pre-log manifest; read as the base, never written)
 *   └── files/{pathHash}/{basename}
 *
 * The renderer and the sidecar each load this module and both record entries
 * for the same conversation. Neither process rewrites a shared document: each
 * record is one appended line, and a reader folds the base plus the log. The
 * per-process cache is checked against the log's byte size before every use,
 * so an append from the other process is seen on the next read.
 *
 * Two entry points feed snapshots into the same kernel:
 *   1. snapshotToolOutputs() — called from toolExecutor after a tool completes,
 *      reuses extractFileOutputs() to discover paths from any tool kind.
 *   2. snapshotUserUpload() — called from chatStore.addMessage when a user
 *      message contains an image (or future file) attachment.
 *
 * One read entry point feeds the UI:
 *   resolveFileSource() — returns 'available' (live or from snapshot),
 *   'skipped' (manifest knows about it but no usable snapshot), or 'missing'.
 *
 * Architecture contract:
 *   ★ If a future change adds stripForDisk-style behavior to a NEW content type
 *     (e.g. DocumentContent gaining a filePath + stripping of base64), that
 *     change MUST also add a corresponding snapshotUserUpload() call, or the
 *     new content type will silently lose data when originals are deleted. ★
 */

import { exists, mkdir, readDir, readTextFile, writeTextFile, remove, stat, copyFile, readFile, writeFile } from '@tauri-apps/plugin-fs';
import { appDataDir, homeDir } from '@tauri-apps/api/path';
import { joinPath, normalizeSeparators, getBaseName } from '@/utils/pathUtils';
import { isMissingPathError } from '@/utils/fsErrors';
import { createConversationPaths, isConversationId, type ConversationPaths } from './conversationPaths';
import { extractFileOutputs } from '@/utils/workflowExtractor';
import { base64ToUint8Array } from '@/utils/base64';
import { RESULT_IMAGE_EXTENSIONS } from '@/utils/imageMediaTypes';
import type { ToolCall } from '@/types';
import type { ToolResultImage } from '../tools/toolResultContent';
import { createLogger } from '../logging/logger';

const logger = createLogger('outputSnapshots');

// ────────────────────────────────────────────────────────────────────────────
// Constants
// ────────────────────────────────────────────────────────────────────────────

/** Single file size cap. Above this, snapshot is skipped with reason='oversized'. */
const MAX_FILE_BYTES = 200 * 1024 * 1024; // 200 MB

/** Bytes of kept copies one conversation holds; beyond it the eviction order below applies. */
const MAX_CONVERSATION_COPY_BYTES = 1024 * 1024 * 1024; // 1 GB

/** Bytes of kept copies all conversations hold together, enforced once per app start. */
const MAX_TOTAL_COPY_BYTES = 5 * 1024 * 1024 * 1024; // 5 GB

/** Manifest schema version */
const MANIFEST_VERSION = 1 as const;

const LEGACY_MANIFEST_FILENAME = 'manifest.json';
const MANIFEST_LOG_FILENAME = 'manifest-log.jsonl';

/** No log file on disk; a cache taken in that state stays valid until one appears. */
const NO_LOG = -1;

/** Identity prefix of a tool-result image, which has no path of its own. */
const TOOL_RESULT_PREFIX = 'tool-result://';

/** refId of an entry installed from an incoming share bundle. */
const SHARED_IMPORT_REF_ID = 'shared-import';

// ────────────────────────────────────────────────────────────────────────────
// Types
// ────────────────────────────────────────────────────────────────────────────

export type SnapshotSource = 'tool-output' | 'user-upload' | 'code-save';
type SnapshotSkipReason = 'oversized' | 'copy-failed' | 'write-failed';

export interface SnapshotEntry {
  /** Normalized original path or stable tool-result:// identity (manifest index key). */
  originalPath: string;
  /** Filename for display */
  basename: string;
  /** Snapshot location relative to outputs/ ; empty string = not snapshotted */
  snapshotRelPath: string;
  /** Bytes */
  size: number;
  /** Original file mtime when snapshot was taken (ms epoch, 0 if unknown) */
  originalMtime: number;
  /** When the snapshot entry was created (ms epoch) */
  snapshottedAt: number;
  /** Where this entry came from */
  source: SnapshotSource;
  /**
   * Reference back to the producing event:
   *   - tool-output: tool_use_id
   *   - user-upload: messageId
   * Currently unused by P0 UI; reserved for P1 traceability features.
   */
  refId: string;
  /**
   * Reference kind:
   *   - tool-output: tool name (write_file, run_command, ...)
   *   - user-upload: 'image' (or future: 'document', etc.)
   * Currently unused by P0 UI; reserved for P1 traceability features.
   */
  refKind: string;
  /** Reason snapshotRelPath is empty. Only set when not snapshotted. */
  skipReason?: SnapshotSkipReason;
}

export interface OutputManifest {
  version: typeof MANIFEST_VERSION;
  /** Keyed by SnapshotEntry.originalPath. */
  entries: Record<string, SnapshotEntry>;
}

export type ResolvedSource =
  | { status: 'available'; path: string; isFromSnapshot: boolean }
  | { status: 'skipped'; entry: SnapshotEntry }
  | { status: 'missing'; basename: string; originalPath: string };

interface SnapshotMeta {
  source: SnapshotSource;
  refId: string;
  refKind: string;
}

/**
 * One line of manifest-log.jsonl. `remove` names the entry it evicts by its
 * `snapshottedAt`, so it never cancels a newer copy of the same path that the
 * other process recorded in the meantime.
 */
type ManifestLogRecord =
  | { op: 'set'; entry: SnapshotEntry }
  | { op: 'remove'; originalPath: string; snapshottedAt: number };

interface CachedManifest {
  manifest: OutputManifest;
  /** Byte size of the log this manifest was folded from, or NO_LOG. */
  logBytes: number;
}

// ────────────────────────────────────────────────────────────────────────────
// Module-level state (caches + locks)
// ────────────────────────────────────────────────────────────────────────────

/**
 * In-memory manifest cache, valid while the log's byte size is unchanged.
 * Without it every FileAttachment render (potentially 100+ per conversation)
 * would read and fold the log; with it a render costs one stat.
 */
const manifestCache = new Map<string, CachedManifest>();

/**
 * Per-conversation serialization lock within this process. Keeps a copy and
 * the record that names it together, and keeps an eviction pass from running
 * twice at once; the other process is never blocked by it, and needs not be,
 * because records are appended.
 */
const convLocks = new Map<string, Promise<unknown>>();

/** Cached conversation path builders */
let cachedPaths: ConversationPaths | null = null;
/** Cached home directory (for ~ expansion) */
let cachedHomeDir: string | null = null;

// ────────────────────────────────────────────────────────────────────────────
// Helpers
// ────────────────────────────────────────────────────────────────────────────

/** Get the outputs/ directory for a specific conversation. Creates if needed. */
async function getOutputsDir(convId: string): Promise<string> {
  if (!cachedPaths) {
    cachedPaths = createConversationPaths(await appDataDir());
  }
  const dir = cachedPaths.outputsDir(convId);
  if (!(await exists(dir))) {
    await mkdir(dir, { recursive: true });
  }
  return dir;
}

/** Normalize a path to canonical form (forward slashes, no trailing slash). */
function normalizePath(p: string): string {
  return normalizeSeparators(p).replace(/\/+$/, '');
}

function normalizeOutputRelPath(relPath: string): string | null {
  const normalized = normalizeSeparators(relPath).replace(/^\/+/, '').replace(/\/+$/, '');
  const segments = normalized.split('/');
  if (!normalized || normalized.startsWith('/') || segments.some((segment) => segment === '.' || segment === '..')) return null;
  return normalized;
}

/** Check if a path looks like an absolute filesystem path (Unix or Windows). */
function isAbsolutePath(p: string): boolean {
  return p.startsWith('/') || /^[A-Za-z]:[\\/]/.test(p);
}

/**
 * Expand a leading `~` to the user's home directory.
 * Returns the original path unchanged if no expansion is needed or homeDir() fails.
 * The AI sometimes emits ~/... paths in chat narrative even though they're not real
 * filesystem paths until expanded.
 */
export async function expandTilde(p: string): Promise<string> {
  if (!p.startsWith('~/') && p !== '~') return p;
  try {
    if (!cachedHomeDir) {
      cachedHomeDir = await homeDir();
    }
    if (p === '~') return cachedHomeDir;
    return joinPath(cachedHomeDir, p.slice(2));
  } catch {
    return p;
  }
}

/**
 * Stable, non-cryptographic hash of a path string.
 * Uses djb2 + length-mix; outputs 16-char base36 string.
 * Collision probability is negligible at conversation scale (a few hundred files).
 */
function hashPath(p: string): string {
  let h = 5381;
  for (let i = 0; i < p.length; i++) {
    h = ((h << 5) + h + p.charCodeAt(i)) | 0;
  }
  // Mix in length so two paths of different lengths can never collide trivially
  return (Math.abs(h).toString(36) + p.length.toString(36)).slice(0, 16).padEnd(8, '0');
}

/**
 * Run an async function under a per-conversation lock.
 * Operations on the same conversation are serialized; different conversations run in parallel.
 */
async function withConvLock<T>(convId: string, fn: () => Promise<T>): Promise<T> {
  const prev = convLocks.get(convId) ?? Promise.resolve();
  const next = prev.then(fn, fn);
  // Track the next-in-line; .catch ensures one failure doesn't poison the chain.
  convLocks.set(convId, next.catch(() => undefined));
  return next;
}

/** Safe stat — returns null if file doesn't exist or stat fails. */
async function safeStat(path: string) {
  try {
    return await stat(path);
  } catch (e) {
    logger.warn('[snapshot] stat failed (capability or missing file?)', { path, err: String(e) });
    return null;
  }
}

// ────────────────────────────────────────────────────────────────────────────
// Manifest read/write (append-only log + size-checked cache)
// ────────────────────────────────────────────────────────────────────────────

/** The manifest written before the log existed: the base every fold starts from. */
async function readLegacyManifest(dir: string, convId: string): Promise<OutputManifest> {
  const path = joinPath(dir, LEGACY_MANIFEST_FILENAME);
  let manifest: OutputManifest = { version: MANIFEST_VERSION, entries: {} };

  try {
    if (await exists(path)) {
      const text = await readTextFile(path);
      const parsed = JSON.parse(text) as OutputManifest;
      if (parsed.version === MANIFEST_VERSION && parsed.entries) {
        manifest = parsed;
      }
    }
  } catch (error) {
    logger.warn('manifest load failed, falling back to empty', {
      convId,
      errorKind: error instanceof Error ? error.name : 'unknown',
    });
  }

  return manifest;
}

function isLogRecord(value: unknown): value is ManifestLogRecord {
  if (typeof value !== 'object' || value === null) return false;
  const record = value as Record<string, unknown>;
  if (record.op === 'remove') {
    return typeof record.originalPath === 'string' && typeof record.snapshottedAt === 'number';
  }
  if (record.op !== 'set' || typeof record.entry !== 'object' || record.entry === null) return false;
  const entry = record.entry as Record<string, unknown>;
  return typeof entry.originalPath === 'string'
    && typeof entry.snapshotRelPath === 'string'
    && typeof entry.snapshottedAt === 'number';
}

function applyRecord(entries: Record<string, SnapshotEntry>, record: ManifestLogRecord): void {
  if (record.op === 'set') {
    entries[record.entry.originalPath] = record.entry;
    return;
  }
  if (entries[record.originalPath]?.snapshottedAt === record.snapshottedAt) {
    delete entries[record.originalPath];
  }
}

function utf8Bytes(text: string): number {
  return new TextEncoder().encode(text).byteLength;
}

/**
 * Fold the log onto the base. A line that is not a record is skipped: a
 * process that dies inside an append can leave part of a line, and every
 * append starts with a newline so that part never joins the next record.
 */
function foldLog(convId: string, text: string, entries: Record<string, SnapshotEntry>): void {
  for (const line of text.split('\n')) {
    if (line.trim() === '') continue;
    let record: unknown;
    try {
      record = JSON.parse(line);
    } catch (error) {
      logger.warn('manifest log line skipped', {
        convId,
        errorKind: error instanceof Error ? error.name : 'unknown',
      });
      continue;
    }
    if (!isLogRecord(record)) {
      logger.warn('manifest log line skipped', { convId, errorKind: 'not-a-record' });
      continue;
    }
    applyRecord(entries, record);
  }
}

async function logBytesOnDisk(dir: string): Promise<number> {
  const path = joinPath(dir, MANIFEST_LOG_FILENAME);
  if (!(await exists(path))) return NO_LOG;
  return (await stat(path)).size;
}

async function readManifestFromDisk(convId: string): Promise<CachedManifest> {
  const dir = await getOutputsDir(convId);
  const manifest = await readLegacyManifest(dir, convId);
  const logPath = joinPath(dir, MANIFEST_LOG_FILENAME);
  if (!(await exists(logPath))) return { manifest, logBytes: NO_LOG };
  // Counted on the bytes read: a line cut inside a multi-byte character
  // decodes to U+FFFD, so the decoded text no longer re-encodes to the size on disk.
  const bytes = await readFile(logPath);
  foldLog(convId, new TextDecoder().decode(bytes), manifest.entries);
  return { manifest, logBytes: bytes.byteLength };
}

async function loadManifest(convId: string): Promise<OutputManifest> {
  const cached = manifestCache.get(convId);
  if (cached && (await logBytesOnDisk(await getOutputsDir(convId))) === cached.logBytes) {
    return cached.manifest;
  }
  return refreshOutputManifest(convId);
}

/**
 * Refresh this process's cache from disk without the size check.
 *
 * conversationStorage calls this immediately before dehydrating inline
 * tool-result images, then reads the cache synchronously through
 * findToolResultImageSnapshot.
 */
export async function refreshOutputManifest(convId: string): Promise<OutputManifest> {
  const fresh = await readManifestFromDisk(convId);
  manifestCache.set(convId, fresh);
  return fresh.manifest;
}

/**
 * Append one record. The leading newline closes a line a dead process left
 * unfinished. A failed append throws to the caller and leaves the cache as it
 * was, so the cache never holds a record the disk does not.
 */
async function appendRecord(convId: string, record: ManifestLogRecord): Promise<void> {
  const dir = await getOutputsDir(convId);
  const line = `\n${JSON.stringify(record)}\n`;
  await writeTextFile(joinPath(dir, MANIFEST_LOG_FILENAME), line, { append: true });
  const cached = manifestCache.get(convId);
  if (cached) {
    applyRecord(cached.manifest.entries, record);
    // Matches the disk only when no other process appended since this cache
    // was taken; otherwise the next loadManifest sees a different size and folds again.
    cached.logBytes = (cached.logBytes === NO_LOG ? 0 : cached.logBytes) + utf8Bytes(line);
  }
}

// ────────────────────────────────────────────────────────────────────────────
// Snapshot kernel
// ────────────────────────────────────────────────────────────────────────────

function buildEntry(
  normalized: string,
  size: number,
  mtime: number,
  meta: SnapshotMeta,
  snapshotRelPath: string,
  options: {
    basename?: string;
    skipReason?: SnapshotSkipReason;
  } = {},
): SnapshotEntry {
  return {
    originalPath: normalized,
    basename: options.basename ?? getBaseName(normalized),
    snapshotRelPath,
    size,
    originalMtime: mtime,
    snapshottedAt: Date.now(),
    source: meta.source,
    refId: meta.refId,
    refKind: meta.refKind,
    ...(options.skipReason ? { skipReason: options.skipReason } : {}),
  };
}

async function recordEntry(convId: string, entry: SnapshotEntry): Promise<SnapshotEntry> {
  await appendRecord(convId, { op: 'set', entry });
  return entry;
}

// ────────────────────────────────────────────────────────────────────────────
// Copy limits
// ────────────────────────────────────────────────────────────────────────────

/**
 * Copies of files that live somewhere else count toward the limits. A
 * tool-result image is the only copy of what the conversation shows, and an
 * attachment installed from a shared bundle is the only copy on this machine;
 * neither counts and neither is evicted.
 */
function evictableRelPath(entry: SnapshotEntry): string | null {
  if (!entry.snapshotRelPath) return null;
  // A size that is not a byte count would turn every total into NaN.
  if (!Number.isFinite(entry.size) || entry.size < 0) return null;
  if (entry.originalPath.startsWith(TOOL_RESULT_PREFIX)) return null;
  if (entry.refId === SHARED_IMPORT_REF_ID) return null;
  const relPath = normalizeOutputRelPath(entry.snapshotRelPath);
  return relPath && relPath.startsWith('files/') ? relPath : null;
}

/**
 * - `unchanged`: the original is where it was, with the size and mtime the copy was taken at.
 * - `gone`: the original is missing or no longer the file the copy was taken of.
 * - `unknown`: the original could not be read (permissions, I/O); the copy may be the only one.
 */
type OriginalState = 'unchanged' | 'gone' | 'unknown';

async function originalState(convId: string, entry: SnapshotEntry): Promise<OriginalState> {
  let st: Awaited<ReturnType<typeof stat>>;
  try {
    st = await stat(entry.originalPath);
  } catch (error) {
    if (isMissingPathError(error)) return 'gone';
    logger.warn('kept copy left out of eviction: its original could not be read', {
      convId,
      errorKind: error instanceof Error ? error.name : 'unknown',
    });
    return 'unknown';
  }
  return st.isFile
    && st.size === entry.size
    && (st.mtime ? st.mtime.getTime() : 0) === entry.originalMtime
    ? 'unchanged'
    : 'gone';
}

interface CopyInConversation {
  convId: string;
  entry: SnapshotEntry;
}

/**
 * Eviction order: first the copies whose original is unchanged in place
 * (evicting them loses nothing today), then the copies that are the only one
 * left; oldest first within each group. A copy whose original cannot be read
 * is not ranked: it stays, and counts toward the limit until a later pass can
 * read its original.
 */
async function inEvictionOrder(copies: CopyInConversation[]): Promise<CopyInConversation[]> {
  const ranked: Array<CopyInConversation & { redundant: boolean }> = [];
  for (const copy of copies) {
    const state = await originalState(copy.convId, copy.entry);
    if (state === 'unknown') continue;
    ranked.push({ ...copy, redundant: state === 'unchanged' });
  }
  ranked.sort((a, b) => Number(b.redundant) - Number(a.redundant)
    || a.entry.snapshottedAt - b.entry.snapshottedAt);
  return ranked;
}

/**
 * Evict one copy. Runs under the conversation lock and re-reads the manifest
 * first, so a copy this process or the other one has replaced since the pass
 * began is left alone. The record goes before the file: a reader in between
 * sees no entry, never an entry whose file is gone.
 *
 * A newer copy of the same path lands on the same file. The manifest is read
 * once more after the record, and the file stays when the other process has
 * recorded a newer copy by then; a copy recorded between that read and the
 * removal still loses its file, and then resolves as not backed up.
 */
async function evictCopy(convId: string, entry: SnapshotEntry): Promise<boolean> {
  const current = (await loadManifest(convId)).entries[entry.originalPath];
  if (!current || current.snapshottedAt !== entry.snapshottedAt) return false;
  const relPath = evictableRelPath(current);
  if (!relPath) return false;
  await appendRecord(convId, { op: 'remove', originalPath: entry.originalPath, snapshottedAt: entry.snapshottedAt });
  if ((await loadManifest(convId)).entries[entry.originalPath]) return true;
  const fullPath = joinPath(await getOutputsDir(convId), relPath);
  if (await exists(fullPath)) await remove(fullPath);
  logger.info('kept copy evicted', { convId, size: entry.size });
  return true;
}

/** Called with the conversation lock held, right after `kept` was recorded. */
async function enforceConversationCopyLimit(convId: string, kept: SnapshotEntry): Promise<void> {
  const counted = Object.values((await loadManifest(convId)).entries).filter((e) => evictableRelPath(e));
  let total = counted.reduce((sum, e) => sum + e.size, 0);
  if (total <= MAX_CONVERSATION_COPY_BYTES) return;
  const candidates = counted
    .filter((e) => e.originalPath !== kept.originalPath)
    .map((entry) => ({ convId, entry }));
  for (const copy of await inEvictionOrder(candidates)) {
    if (total <= MAX_CONVERSATION_COPY_BYTES) break;
    if (await evictCopy(convId, copy.entry)) total -= copy.entry.size;
  }
}

/** The pass in flight, so a second caller in this process joins it. */
let totalLimitPass: Promise<void> | null = null;

/**
 * Hold the copies of all conversations under MAX_TOTAL_COPY_BYTES. Run once
 * per app start. A conversation `isBusy` reports as running counts toward the
 * total and loses none of its copies; it is asked again right before each
 * eviction, because a run can start while the pass is ranking copies.
 */
export function enforceTotalCopyLimit(isBusy: (convId: string) => boolean): Promise<void> {
  totalLimitPass ??= runTotalCopyLimit(isBusy).finally(() => { totalLimitPass = null; });
  return totalLimitPass;
}

async function runTotalCopyLimit(isBusy: (convId: string) => boolean): Promise<void> {
  if (!cachedPaths) {
    cachedPaths = createConversationPaths(await appDataDir());
  }
  const paths = cachedPaths;
  if (!(await exists(paths.root))) return;

  let total = 0;
  const candidates: CopyInConversation[] = [];
  for (const dirEntry of await readDir(paths.root)) {
    if (!dirEntry.isDirectory || !isConversationId(dirEntry.name)) continue;
    const convId = dirEntry.name;
    if (!(await exists(paths.outputsDir(convId)))) continue;
    for (const entry of Object.values((await loadManifest(convId)).entries)) {
      if (!evictableRelPath(entry)) continue;
      total += entry.size;
      if (!isBusy(convId)) candidates.push({ convId, entry });
    }
  }
  if (total <= MAX_TOTAL_COPY_BYTES) return;

  for (const copy of await inEvictionOrder(candidates)) {
    if (total <= MAX_TOTAL_COPY_BYTES) break;
    if (isBusy(copy.convId)) continue;
    if (await withConvLock(copy.convId, () => evictCopy(copy.convId, copy.entry))) total -= copy.entry.size;
  }
}

/**
 * Snapshot a single file. Idempotent: subsequent calls for the same originalPath
 * overwrite the previous snapshot (so edit_file etc. naturally produce "latest version" semantics).
 *
 * Returns the resulting manifest entry, or null if the file should not be snapshotted
 * (path invalid, file gone, target is a directory, etc.).
 */
export async function snapshotFile(
  convId: string,
  rawPath: string,
  meta: SnapshotMeta,
): Promise<SnapshotEntry | null> {
  if (!rawPath) return null;
  // Expand ~/... before normalization — AI tools sometimes pass home-relative paths
  // through their input even when the underlying tool expands them internally.
  const expanded = await expandTilde(rawPath);
  const normalized = normalizePath(expanded);
  if (!isAbsolutePath(normalized)) {
    logger.warn('[snapshot] rejected non-absolute path', { rawPath, normalized });
    return null;
  }

  return withConvLock(convId, () => snapshotFileNormalized(convId, normalized, meta));
}

/** snapshotFile copy route once its path is normalized and conversation lock held. */
async function snapshotFileNormalized(
  convId: string,
  normalized: string,
  meta: SnapshotMeta,
  identityPath: string = normalized,
  targetBasename: string = getBaseName(normalized),
): Promise<SnapshotEntry | null> {
  const outputsDir = await getOutputsDir(convId);
  // Idempotency guard: don't snapshot files already inside outputs/
  // (prevents recursion when AI writes directly to the session output dir)
  if (identityPath === normalized && normalized.startsWith(outputsDir)) return null;

  const st = await safeStat(normalized);
  if (!st || !st.isFile) return null;

  const mtimeMs = st.mtime ? st.mtime.getTime() : 0;

  // Oversized check
  if (st.size > MAX_FILE_BYTES) {
    logger.info('snapshot skipped: oversized', { convId, path: normalized, size: st.size });
    return await recordEntry(
      convId,
      buildEntry(identityPath, st.size, mtimeMs, meta, '', {
        basename: targetBasename,
        skipReason: 'oversized',
      }),
    );
  }

  // Copy
  const identityHash = hashPath(identityPath);
  const subdir = joinPath(outputsDir, 'files', identityHash);
  const dest = joinPath(subdir, targetBasename);
  try {
    if (!(await exists(subdir))) {
      await mkdir(subdir, { recursive: true });
    }
    await copyFile(normalized, dest);
  } catch (e) {
    logger.warn('snapshot copy failed', { convId, src: normalized, err: e });
    return await recordEntry(
      convId,
      buildEntry(identityPath, st.size, mtimeMs, meta, '', {
        basename: targetBasename,
        skipReason: 'copy-failed',
      }),
    );
  }

  const kept = await recordEntry(
    convId,
    buildEntry(identityPath, st.size, mtimeMs, meta, `files/${identityHash}/${targetBasename}`, {
      basename: targetBasename,
    }),
  );
  if (evictableRelPath(kept)) await enforceConversationCopyLimit(convId, kept);
  return kept;
}

// ────────────────────────────────────────────────────────────────────────────
// Public capture entry points
// ────────────────────────────────────────────────────────────────────────────

/**
 * Snapshot all output files produced by a single tool call.
 * Reuses extractFileOutputs() to discover paths from any tool kind (write_file,
 * edit_file, run_command stdout/cmd parsing, generate_image, MCP, etc.).
 *
 * Note: extractFileOutputs has a "intermediate script filter" that operates on
 * the FULL toolCalls array (it knows which .py/.js scripts were later executed).
 * When called per-toolCall here, that filter is ineffective — intermediate scripts
 * may also be snapshotted. This is accepted as a minor space cost (KB-level)
 * with no functional impact.
 */
export async function snapshotToolOutputs(
  convId: string,
  toolCall: { id: string; name: string; input: Record<string, unknown>; result: string },
  workspacePath?: string | null,
): Promise<void> {
  const outputs = extractFileOutputs([toolCall as ToolCall], { mode: 'deliverables', includeReads: false });
  const targets = outputs.filter((o) => o.operation === 'create' || o.operation === 'write');
  if (targets.length === 0) return;

  for (const { path } of targets) {
    // Resolve relative paths against the workspace so snapshotFile can stat them.
    const resolvedPath = (!isAbsolutePath(path) && workspacePath)
      ? joinPath(workspacePath, path)
      : path;
    await snapshotFile(convId, resolvedPath, {
      source: 'tool-output',
      refId: toolCall.id,
      refKind: toolCall.name,
    });
  }
}

/**
 * Snapshot a file uploaded by the user (currently only images).
 * Called fire-and-forget from chatStore.addMessage when a user message
 * contains an ImageContent block with a filePath.
 */
export async function snapshotUserUpload(
  convId: string,
  filePath: string,
  messageId: string,
  kind: 'image',
): Promise<void> {
  await snapshotFile(convId, filePath, {
    source: 'user-upload',
    refId: messageId,
    refKind: kind,
  });
}

/**
 * Persist an image returned in a tool result.
 *
 * A read_file result can retain the original path and therefore uses the same
 * copy-based snapshot route as every other filesystem file. Computer-use
 * screenshots have no source path, so their base64 bytes are materialised
 * directly under the ordinary outputs/files/{hash}/ layout instead.
 */
export async function snapshotResultImage(
  convId: string,
  toolCallId: string,
  imageBlock: ToolResultImage,
  sourcePath?: string,
): Promise<void> {
  if (!toolCallId || !imageBlock.base64) return;
  const imageBase64 = imageBlock.base64;

  const extension = RESULT_IMAGE_EXTENSIONS[imageBlock.mediaType.toLowerCase()];
  if (!extension) {
    logger.warn('[snapshot] unsupported result image media type', { mediaType: imageBlock.mediaType });
    return;
  }

  const meta: SnapshotMeta = {
    source: 'tool-output',
    refId: toolCallId,
    refKind: 'result-image',
  };
  const originalPath = `${TOOL_RESULT_PREFIX}${toolCallId}`;
  const hash = hashPath(originalPath);
  // Never use the provider-controlled toolCallId as a path segment. Its stable
  // identity lives in the manifest; the hashed directory + fixed basename keep
  // `..`, slashes and platform-invalid characters out of the filesystem path.
  const basename = `result.${extension}`;

  await withConvLock(convId, async () => {
    const manifest = await loadManifest(convId);
    const alreadySnapshotted = Object.values(manifest.entries).some(
      (entry) => entry.source === meta.source && entry.refId === meta.refId && entry.refKind === meta.refKind,
    );
    if (alreadySnapshotted) return;

    if (sourcePath) {
      const expanded = await expandTilde(sourcePath);
      const normalized = normalizePath(expanded);
      if (!isAbsolutePath(normalized)) {
        logger.warn('[snapshot] rejected non-absolute result image path', { sourcePath, normalized });
      } else {
        await snapshotFileNormalized(convId, normalized, meta, originalPath, basename);
        return;
      }
    }

    let decodedSize = 0;
    try {
      const bytes = base64ToUint8Array(imageBase64);
      decodedSize = bytes.byteLength;
      if (decodedSize > MAX_FILE_BYTES) {
        logger.info('[snapshot] result image skipped: oversized', {
          convId,
          toolCallId,
          size: decodedSize,
        });
        await recordEntry(convId, buildEntry(originalPath, decodedSize, 0, meta, '', {
          basename,
          skipReason: 'oversized',
        }));
        return;
      }

      const outputsDir = await getOutputsDir(convId);
      const subdir = joinPath(outputsDir, 'files', hash);
      const targetPath = joinPath(subdir, basename);
      if (!(await exists(subdir))) await mkdir(subdir, { recursive: true });
      await writeFile(targetPath, bytes);
      await recordEntry(convId, buildEntry(
        originalPath,
        decodedSize,
        0,
        meta,
        `files/${hash}/${basename}`,
        { basename },
      ));
    } catch (e) {
      logger.warn('[snapshot] result image write failed', { convId, toolCallId, err: e });
      await recordEntry(convId, buildEntry(originalPath, decodedSize, 0, meta, '', {
        basename,
        skipReason: 'write-failed',
      }));
    }
  });
}

/**
 * Snapshot a file the user manually saved from a markdown code block in chat.
 * Called fire-and-forget from MarkdownRenderer.handleSaveAs after a successful
 * write. Without this, code-block-saved files are at the mercy of the user's
 * file management — exactly the case the snapshot system is meant to protect.
 */
export async function snapshotCodeBlockSave(
  convId: string,
  filePath: string,
  language: string | undefined,
): Promise<void> {
  await snapshotFile(convId, filePath, {
    source: 'code-save',
    refId: '',  // no message context — code blocks don't have a stable id
    refKind: language || 'text',
  });
}

// ────────────────────────────────────────────────────────────────────────────
// Public read entry point
// ────────────────────────────────────────────────────────────────────────────

/**
 * Resolve where to actually load a file from when rendering a card.
 * Priority chain:
 *   1. Live original (when path is absolute and exists)
 *   2. Session outputs/ probe by basename — covers two real cases:
 *      a. AI followed the no-workspace prompt and wrote directly to outputDir,
 *         then the chat narrative mentions only a bare basename.
 *      b. The path was passed through markdown text-extraction and lost its
 *         directory part.
 *   3. Snapshot fallback via manifest
 *   4. skipped (manifest entry exists but no usable copy)
 *   5. missing
 */
export async function resolveFileSource(
  convId: string | undefined,
  originalPath: string,
  workspacePath?: string | null,
): Promise<ResolvedSource> {
  const basename = getBaseName(originalPath);

  // 0. Expand `~/...` if present — AI sometimes emits home-relative paths in narrative text.
  const expandedPath = await expandTilde(originalPath);

  // 1. Live original takes priority — even if a snapshot exists, the user's
  //    in-place edits should be reflected.
  if (expandedPath && isAbsolutePath(expandedPath)) {
    if (await exists(expandedPath)) {
      return { status: 'available', path: expandedPath, isFromSnapshot: false };
    }
  }

  // 1.5. Relative path + known workspace — probe workspace-relative location.
  // Handles the case where the AI wrote a file with a bare name (e.g. "报告.docx")
  // relative to the workspace CWD; extractFileOutputs captures the bare basename
  // and the snapshot was stored under the absolute path, but the live file check
  // (step 1) was skipped because the path isn't absolute.
  if (!isAbsolutePath(expandedPath ?? '') && basename && workspacePath) {
    const candidate = joinPath(workspacePath, basename);
    if (await exists(candidate)) {
      return { status: 'available', path: candidate, isFromSnapshot: false };
    }
  }

  // 2. Session outputs/ top-level probe (handles AI-wrote-to-outputDir directly case)
  if (convId && basename) {
    try {
      const outputsDir = await getOutputsDir(convId);
      const candidate = joinPath(outputsDir, basename);
      if (await exists(candidate)) {
        return { status: 'available', path: candidate, isFromSnapshot: false };
      }
    } catch {
      // ignore — fall through to manifest lookup
    }
  }

  // 3. Fall back to snapshot via manifest
  if (convId) {
    const manifest = await loadManifest(convId);

    // 3a. Exact path match (the common case — toolCall input.path matches the lookup)
    const exactEntry = manifest.entries[normalizePath(expandedPath)];
    if (exactEntry) {
      if (exactEntry.snapshotRelPath) {
        const dir = await getOutputsDir(convId);
        const full = joinPath(dir, exactEntry.snapshotRelPath);
        if (await exists(full)) {
          return { status: 'available', path: full, isFromSnapshot: true };
        }
      }
      // Manifest knows but no usable snapshot file
      return { status: 'skipped', entry: exactEntry };
    }

    // 3b. Basename match — handles "AI text mentioned bare basename" case where the
    //      lookup path lacks directory info but a manifest entry exists for the same filename.
    if (basename) {
      const basenameMatch = Object.values(manifest.entries).find(
        (e) => e.basename === basename && e.snapshotRelPath,
      );
      if (basenameMatch) {
        const dir = await getOutputsDir(convId);
        const full = joinPath(dir, basenameMatch.snapshotRelPath);
        if (await exists(full)) {
          return { status: 'available', path: full, isFromSnapshot: true };
        }
      }
    }
  }

  // 4. No record at all
  return { status: 'missing', basename, originalPath };
}

/**
 * Resolve a persisted tool-result outputRef by its path relative to outputs/.
 * This is intentionally separate from manifest path lookup: outputRef is already
 * the post-snapshot identity, so basename fallback would risk loading the wrong
 * file when two tool images share a filename.
 */
export async function resolveOutputRefSource(
  convId: string | undefined,
  relPath: string,
): Promise<ResolvedSource> {
  const normalizedRelPath = normalizeOutputRelPath(relPath);
  const basename = getBaseName(normalizedRelPath ?? relPath);
  if (!convId || !normalizedRelPath) {
    return { status: 'missing', basename, originalPath: relPath };
  }

  try {
    const outputsDir = await getOutputsDir(convId);
    const fullPath = joinPath(outputsDir, normalizedRelPath);
    const normalizedFullPath = normalizePath(fullPath);
    const normalizedOutputsDir = normalizePath(outputsDir);
    if (!normalizedFullPath.startsWith(`${normalizedOutputsDir}/`)) {
      return { status: 'missing', basename, originalPath: relPath };
    }
    if (await exists(fullPath)) {
      return { status: 'available', path: fullPath, isFromSnapshot: true };
    }
  } catch {
    // fall through to missing
  }

  return { status: 'missing', basename, originalPath: relPath };
}

/**
 * Synchronous dehydration guard for conversationStorage. Storage refreshes the
 * process-local manifest cache from disk before serializing inline tool-result
 * images, then uses this exact-entry lookup while cloning the message for disk.
 */
export function findToolResultImageSnapshot(convId: string | undefined, toolCallId: string): SnapshotEntry | null {
  if (!convId || !toolCallId) return null;
  const entry = manifestCache.get(convId)?.manifest.entries[`${TOOL_RESULT_PREFIX}${toolCallId}`];
  if (
    entry
    && entry.source === 'tool-output'
    && entry.refId === toolCallId
    && entry.refKind === 'result-image'
    && entry.snapshotRelPath
  ) {
    return entry;
  }
  return null;
}


// ────────────────────────────────────────────────────────────────────────────
// Cleanup
// ────────────────────────────────────────────────────────────────────────────

/**
 * Clean up all snapshot state for a conversation.
 *
 * Note: deleteConversationFiles() in conversationStorage already rm -rf's the
 * entire conversation directory, which includes outputs/. This function is
 * therefore mostly redundant for the disk side, but it MUST be called to
 * clear the in-memory manifest cache. Otherwise stale entries linger.
 */
export async function cleanupConversationOutputs(convId: string): Promise<void> {
  manifestCache.delete(convId);
  convLocks.delete(convId);

  // Defensive: also try to remove the dir directly, in case the caller didn't
  // also call deleteConversationFiles. swallow errors (already-deleted is fine).
  try {
    if (!cachedPaths) {
      cachedPaths = createConversationPaths(await appDataDir());
    }
    const dir = cachedPaths.outputsDir(convId);
    if (await exists(dir)) {
      await remove(dir, { recursive: true });
    }
  } catch {
    // Non-critical
  }
}

// ────────────────────────────────────────────────────────────────────────────
// Read-only helpers (used by share export — never mutate manifest)
// ────────────────────────────────────────────────────────────────────────────

/** List all snapshot entries for a conversation. Returns [] if none. */
export async function listSnapshots(convId: string): Promise<SnapshotEntry[]> {
  const manifest = await loadManifest(convId);
  return Object.values(manifest.entries);
}

/**
 * Read a snapshot's raw bytes by relative path (as stored in SnapshotEntry.snapshotRelPath).
 * Returns null if the snapshot file is missing or the path escapes the outputs dir.
 */
export async function readSnapshotBytes(convId: string, snapshotRelPath: string): Promise<Uint8Array | null> {
  if (!snapshotRelPath) return null;
  const outputsDir = await getOutputsDir(convId);
  const fullPath = joinPath(outputsDir, snapshotRelPath);
  // Defense-in-depth: ensure the resolved path stays inside outputsDir
  const normalizedOutputsDir = `${normalizePath(outputsDir)}/`;
  const normalizedFullPath = normalizePath(fullPath);
  if (normalizedFullPath !== normalizePath(outputsDir) && !normalizedFullPath.startsWith(normalizedOutputsDir)) return null;
  try {
    if (!(await exists(fullPath))) return null;
    const bytes = await readFile(fullPath);
    return bytes;
  } catch {
    return null;
  }
}

// ────────────────────────────────────────────────────────────────────────────
// Share import: materialise attachments carried in an incoming bundle
// ────────────────────────────────────────────────────────────────────────────

/** Minimal shape installSharedAttachments needs — mirrors ShareAttachment in
 *  shareBundle.ts. Duplicated locally so this module stays free of a
 *  reverse core->core dependency. */
export interface ShareAttachmentInput {
  basename: string;
  originalPath: string;
  source: SnapshotSource;
  sizeBytes: number;
  /** Base64 payload. Entries without `data` are skipped (user-upload-excluded,
   *  oversized, missing, budget-exceeded — already filtered by the sender). */
  data?: string;
}

export interface InstallSharedAttachmentsResult {
  installed: number;
  skipped: number;
}

/**
 * Write AI-generated files that were carried inside an incoming share bundle
 * to this conversation's outputs/ dir, registering each in the manifest so
 * file cards resolve to a real on-disk snapshot (instead of "missing").
 *
 * Path rule: the manifest key is `normalizePath(expandTilde(incoming))` —
 * exactly what `resolveFileSource` looks up at render time. Basename
 * fallback in that function (rule 3b) covers any residual home-dir
 * mismatch between sender and recipient.
 *
 * Failures per-entry are swallowed and counted in `skipped` rather than
 * aborting the whole install — a single bad entry should not block the
 * rest of the conversation from importing cleanly.
 */
export async function installSharedAttachments(
  convId: string,
  attachments: Record<string, ShareAttachmentInput>,
): Promise<InstallSharedAttachmentsResult> {
  let installed = 0;
  let skipped = 0;
  const outputsDir = await getOutputsDir(convId);

  for (const entry of Object.values(attachments)) {
    if (!entry.data) { skipped++; continue; }
    try {
      const expandedPath = await expandTilde(entry.originalPath);
      const keyPath = normalizePath(expandedPath);
      const hash = hashPath(keyPath);
      const subdir = joinPath(outputsDir, 'files', hash);
      if (!(await exists(subdir))) await mkdir(subdir, { recursive: true });
      const targetPath = joinPath(subdir, entry.basename);
      const bytes = base64ToUint8Array(entry.data);
      await writeFile(targetPath, bytes);

      const snapshotEntry: SnapshotEntry = {
        originalPath: keyPath,
        basename: entry.basename,
        snapshotRelPath: `files/${hash}/${entry.basename}`,
        size: entry.sizeBytes,
        originalMtime: 0,
        snapshottedAt: Date.now(),
        source: entry.source,
        refId: SHARED_IMPORT_REF_ID,
        refKind: 'shared',
      };
      await recordEntry(convId, snapshotEntry);
      installed++;
    } catch (e) {
      logger.warn('installSharedAttachments: entry failed', { basename: entry.basename, err: e });
      skipped++;
    }
  }

  return { installed, skipped };
}

// ────────────────────────────────────────────────────────────────────────────
// Test-only exports (do not import from production code)
// ────────────────────────────────────────────────────────────────────────────

/** @internal — exposed for unit tests only */
export const __testing = {
  hashPath,
  normalizePath,
  normalizeOutputRelPath,
  isAbsolutePath,
  loadManifest,
  refreshOutputManifest,
  /** Seed the cache as if folded from a conversation with no log on disk. */
  setManifest: (convId: string, manifest: OutputManifest) => {
    manifestCache.set(convId, { manifest, logBytes: NO_LOG });
  },
  resetCaches: () => {
    manifestCache.clear();
    convLocks.clear();
    cachedPaths = null;
  },
  MAX_FILE_BYTES,
  MAX_CONVERSATION_COPY_BYTES,
  MAX_TOTAL_COPY_BYTES,
};
